   124→/// Returns the rpc limits for beacon_block_by_range and beacon_block_by_root responses.
   125→///
   126→/// Note: This function should take care to return the min/max limits accounting for all
   127→/// previous valid forks when adding a new fork variant.
   128→pub fn rpc_block_limits_by_fork(current_fork: ForkName) -> RpcLimits {
   129→    match &current_fork {
   130→        ForkName::Base => {
   131→            RpcLimits::new(*SIGNED_BEACON_BLOCK_BASE_MIN, *SIGNED_BEACON_BLOCK_BASE_MAX)
   132→        }
   133→        ForkName::Altair => RpcLimits::new(
   134→            *SIGNED_BEACON_BLOCK_BASE_MIN, // Base block is smaller than altair blocks
   135→            *SIGNED_BEACON_BLOCK_ALTAIR_MAX, // Altair block is larger than base blocks
   136→        ),
   137→        // After the merge the max SSZ size of a block is absurdly big. The size is actually
   138→        // bound by other constants, so here we default to the bellatrix's max value
   139→        _ => RpcLimits::new(
   140→            *SIGNED_BEACON_BLOCK_BASE_MIN, // Base block is smaller than altair and bellatrix blocks
   141→            *SIGNED_BEACON_BLOCK_BELLATRIX_MAX, // Bellatrix block is larger than base and altair blocks
   142→        ),
   143→    }
   144→}
