     6→/// Accumulates results of a data_columns_by_range request. Only returns items after receiving the
     7→/// stream termination.
     8→pub struct DataColumnsByRangeRequestItems<E: EthSpec> {
     9→    request: DataColumnsByRangeRequest,
    10→    items: Vec<Arc<DataColumnSidecar<E>>>,
    11→}
    12→
    13→impl<E: EthSpec> DataColumnsByRangeRequestItems<E> {
    14→    pub fn new(request: DataColumnsByRangeRequest) -> Self {
    15→        Self {
    16→            request,
    17→            items: vec![],
    18→        }
    19→    }
    20→}
    21→
    22→impl<E: EthSpec> ActiveRequestItems for DataColumnsByRangeRequestItems<E> {
    23→    type Item = Arc<DataColumnSidecar<E>>;
    24→
    25→    fn add(&mut self, data_column: Self::Item) -> Result<bool, LookupVerifyError> {
    26→        if data_column.slot() < self.request.start_slot
    27→            || data_column.slot() >= self.request.start_slot + self.request.count
    28→        {
    29→            return Err(LookupVerifyError::UnrequestedSlot(data_column.slot()));
    30→        }
    31→        if !self.request.columns.contains(&data_column.index) {
    32→            return Err(LookupVerifyError::UnrequestedIndex(data_column.index));
    33→        }
    34→        if !data_column.verify_inclusion_proof() {
    35→            return Err(LookupVerifyError::InvalidInclusionProof);
    36→        }
    37→        if self.items.iter().any(|existing| {
    38→            existing.slot() == data_column.slot() && existing.index == data_column.index
    39→        }) {
    40→            return Err(LookupVerifyError::DuplicatedData(
    41→                data_column.slot(),
    42→                data_column.index,
    43→            ));
    44→        }
    45→
    46→        self.items.push(data_column);
    47→
    48→        Ok(self.items.len() >= self.request.count as usize * self.request.columns.len())
    49→    }
    50→
    51→    fn consume(&mut self) -> Vec<Self::Item> {
    52→        std::mem::take(&mut self.items)
    53→    }
    54→}
