     6→/// Accumulates results of a blobs_by_range request. Only returns items after receiving the
     7→/// stream termination.
     8→pub struct BlobsByRangeRequestItems<E: EthSpec> {
     9→    request: BlobsByRangeRequest,
    10→    items: Vec<Arc<BlobSidecar<E>>>,
    11→    max_blobs_per_block: u64,
    12→}
    13→
    14→impl<E: EthSpec> BlobsByRangeRequestItems<E> {
    15→    pub fn new(request: BlobsByRangeRequest, max_blobs_per_block: u64) -> Self {
    16→        Self {
    17→            request,
    18→            items: vec![],
    19→            max_blobs_per_block,
    20→        }
    21→    }
    22→}
    23→
    24→impl<E: EthSpec> ActiveRequestItems for BlobsByRangeRequestItems<E> {
    25→    type Item = Arc<BlobSidecar<E>>;
    26→
    27→    fn add(&mut self, blob: Self::Item) -> Result<bool, LookupVerifyError> {
    28→        if blob.slot() < self.request.start_slot
    29→            || blob.slot() >= self.request.start_slot + self.request.count
    30→        {
    31→            return Err(LookupVerifyError::UnrequestedSlot(blob.slot()));
    32→        }
    33→        if blob.index >= self.max_blobs_per_block {
    34→            return Err(LookupVerifyError::UnrequestedIndex(blob.index));
    35→        }
    36→        if !blob.verify_blob_sidecar_inclusion_proof() {
    37→            return Err(LookupVerifyError::InvalidInclusionProof);
    38→        }
    39→        if self
    40→            .items
    41→            .iter()
    42→            .any(|existing| existing.slot() == blob.slot() && existing.index == blob.index)
    43→        {
    44→            return Err(LookupVerifyError::DuplicatedData(blob.slot(), blob.index));
    45→        }
    46→
    47→        self.items.push(blob);
    48→
    49→        // Skip check if blobs are ready as it's rare that all blocks have max blobs
    50→        Ok(false)
    51→    }
    52→
    53→    fn consume(&mut self) -> Vec<Self::Item> {
    54→        std::mem::take(&mut self.items)
    55→    }
    56→}
