    38→/// Given a set of nodes that reference each other, returns a list of chains with unique tips that
    39→/// contain at least two elements. In descending slot order (tip first).
    40→pub(crate) fn compute_parent_chains(nodes: &[Node]) -> Vec<NodeChain> {
    41→    let mut child_to_parent = HashMap::new();
    42→    let mut parent_to_child = HashMap::<Hash256, Vec<Hash256>>::new();
    43→    for node in nodes {
    44→        child_to_parent.insert(node.block_root, node.parent_root);
    45→        if let Some(parent_root) = node.parent_root {
    46→            parent_to_child
    47→                .entry(parent_root)
    48→                .or_default()
    49→                .push(node.block_root);
    50→        }
    51→    }
    52→
    53→    let mut parent_chains = vec![];
    54→
    55→    // Iterate blocks with no children
    56→    for tip in nodes {
    57→        let mut block_root = tip.block_root;
    58→        if !parent_to_child.contains_key(&block_root) {
    59→            let mut chain = vec![];
    60→
    61→            // Resolve chain of blocks
    62→            while let Some(parent_root) = child_to_parent.get(&block_root) {
    63→                // block_root is a known block that may or may not have a parent root
    64→                chain.push(block_root);
    65→                if let Some(parent_root) = parent_root {
    66→                    block_root = *parent_root;
    67→                } else {
    68→                    break;
    69→                }
    70→            }
    71→
    72→            if chain.len() > 1 {
    73→                parent_chains.push(NodeChain {
    74→                    chain,
    75→                    tip: tip.block_root,
    76→                });
    77→            }
    78→        }
    79→    }
    80→
    81→    parent_chains
    82→}
